def test_cosh_acos_acosh_recursion_depth():
    import pytest
    from sympy import cosh, acos, acosh, I, symbols
    g = symbols('g')
    expr = cosh(acos(-I + acosh(-g + I)))
    try:
        result = expr.is_zero
    except RecursionError as e:
        pytest.fail(f"RecursionError raised when accessing is_zero: {e}")
    assert result in (True, False, None)
